insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0004-0000-4000-8000-00000000003a', 'en', null, 'Introduction to Public Health', 'Public health is the science and practice of protecting and improving the health of whole populations, not just individual patients. This course introduces its core ideas - prevention, epidemiology, the determinants of health, disease control, and the systems and policies that keep communities well. Structure adapted from the public health overview on Wikipedia, the free encyclopedia (CC BY-SA 4.0).', null, 'foundations', 56, true, 'science', '{}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0004-0000-4000-8000-00000000003a', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"Public health differs from clinical medicine mainly because it focuses on...","options":["one patient at a time","whole populations and prevention","surgery and hospital care only","medical billing"],"answer":1,"explanation":"Clinical medicine treats individuals; public health works to keep entire populations healthy, with a strong emphasis on prevention."},{"prompt":"Primary prevention aims to...","options":["cure advanced disease","stop disease before it starts","rehabilitate after injury","detect disease early in symptom-free people"],"answer":1,"explanation":"Primary prevention acts before disease appears - vaccines, clean water, and safety laws are examples. Early detection is secondary prevention."},{"prompt":"The number of NEW cases of a disease arising in a period is called...","options":["prevalence","incidence","mortality","immunity"],"answer":1,"explanation":"Incidence counts new cases over time; prevalence counts all existing cases at a point in time."},{"prompt":"Vaccination can protect even unvaccinated people in a community through...","options":["herd immunity","antibiotics","quarantine fines","water chlorination"],"answer":0,"explanation":"When enough of a population is immune, a pathogen struggles to spread, indirectly shielding those who are not immune."},{"prompt":"A leading behavioral risk factor for chronic disease worldwide is...","options":["tobacco use","reading","getting vaccinated","washing hands"],"answer":0,"explanation":"Tobacco use, poor diet, physical inactivity, and harmful alcohol use are major drivers of heart disease, cancer, and diabetes."},{"prompt":"The phrase ''social determinants of health'' refers to...","options":["genetics alone","conditions like income, housing, and education that shape health","the size of a hospital","the price of medicines only"],"answer":1,"explanation":"The conditions in which people are born, grow, work, and age strongly influence health, often more than medical care does."},{"prompt":"Which disease was declared eradicated worldwide in 1980 after a global vaccination campaign?","options":["malaria","smallpox","polio","cholera"],"answer":1,"explanation":"Smallpox is the only human disease ever eradicated, a landmark achievement of coordinated public health."},{"prompt":"The international agency that coordinates global public health is the...","options":["World Health Organization","World Bank","United Nations Security Council","International Monetary Fund"],"answer":0,"explanation":"The World Health Organization, founded in 1948, sets standards, tracks diseases, and coordinates responses across countries."}]}'::jsonb, null, 10),
  (2, 'What public health is', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"By the end of this lesson you will be able to say clearly what public health is, explain how it differs from clinical medicine, and describe why prevention sits at its center. You will be able to give the difference between a population view and an individual view of health, and offer an everyday example of each. Warm-up: from the diagnostic, which matters more to public health - treating one sick person extremely well, or stopping a thousand people from getting sick in the first place? Hold that thought as you read, because the honest answer is that a strong health system needs both, but public health specializes in the second. Think of a single word that captures what public health tries to prevent, and check whether your definition still fits once you reach the end of the section on key methods below."},{"heading":"The idea","text":"Public health is the organized effort of society to protect and improve the health of populations rather than of single patients. A clinician asks what is wrong with this person and how to treat them. A public health worker asks why people in this community keep getting this illness and how to stop it across the whole group. The population lens changes everything: the unit of concern is the group, the main tool is prevention rather than cure, and success is measured in cases that never happened. Because disease has causes upstream of the clinic - unsafe water, polluted air, poverty, tobacco, unsafe roads - public health reaches beyond hospitals into housing, schools, workplaces, and law. It draws on many fields at once, including epidemiology, biology, statistics, economics, and social science. It is also deeply practical and collective: no single person can clean a city water supply or run a vaccination program alone. Clinical care and public health are partners, not rivals. The clinic saves the patient in front of you; public health works so that fewer patients ever arrive."},{"heading":"Key methods & examples","text":"Consider clean drinking water. A doctor can treat a child sick with cholera, but a water utility that filters and chlorinates the supply prevents thousands of such illnesses at once - that is the public health approach, and it has saved more lives than almost any medicine. Seatbelt and speed laws are another example: no drug reduces crash deaths as broadly as changing the conditions in which people drive. A third example is tobacco control. Clinicians treat lung cancer one patient at a time, while public health raises tobacco taxes, bans indoor smoking, and funds quit programs, cutting the number of new smokers across a whole country. Notice the pattern in each case: the intervention targets the environment, the system, or the whole population, and its payoff is measured in events that did not occur. This is why public health work can feel invisible. When it succeeds, the result is an absence - fewer outbreaks, fewer injuries, fewer early deaths - rather than a dramatic individual rescue. The quiet nature of prevention is a core theme of the field."},{"heading":"Your turn","text":"Try these, then check the answers below. 1) In one sentence, how does public health differ from clinical medicine? 2) Give an example of a public health action that works by changing the environment rather than treating a person. 3) True or false: a successful prevention program is often invisible because it produces events that never happen. 4) Which professional treats the individual patient, and which protects the population? 5) Name two fields besides medicine that public health draws on. Answers: 1) Public health protects and improves the health of whole populations through prevention, while clinical medicine diagnoses and treats individual patients. 2) Chlorinating a city water supply, or passing seatbelt laws, are good examples. 3) True - its payoff is measured in cases that did not occur. 4) The clinician treats the individual; the public health system protects the population. 5) Any two of epidemiology, statistics, economics, social science, biology, or environmental science."},{"heading":"Common mistakes & exit ticket","text":"A common mistake is to think public health is just medicine done on a larger scale. It is not: it is a distinct discipline centered on prevention, populations, and the conditions that make people healthy or sick. Another mistake is to treat prevention and treatment as competitors. In reality a good society funds both, and they reinforce each other. A third mistake is to judge public health only by dramatic rescues; its biggest wins are quiet and statistical, like a city that simply stops having cholera outbreaks. Exit ticket: (a) What is the unit of concern in public health - the individual or the population? (b) What is the field''s central strategy for improving health? (c) Why do successful prevention programs often go unnoticed? Answers: (a) the population; (b) prevention, acting on causes before disease appears; (c) because their success shows up as events that never happen, so there is no visible crisis to point to."}]}'::jsonb, 'Clinical medicine treats the patient in front of you; public health protects the whole population that patient belongs to - both matter, and they work best together.', 12),
  (3, 'Core functions and the three levels of prevention', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"After this lesson you will be able to list the core functions that every public health system performs, and you will be able to place any health action into one of the three levels of prevention: primary, secondary, or tertiary. You will be able to explain what each level targets and give a clear example of each. Warm-up: think of one thing you did this week that helped keep you healthy. Was it stopping a problem before it could start, catching a problem early, or managing a problem you already have? Keep your example in mind, because by the end you will be able to name exactly which level of prevention it belongs to. This simple three-part frame is one of the most useful tools in public health, and you will use it in almost every later lesson, from vaccination to chronic disease to screening programs."},{"heading":"The idea","text":"Public health systems are often described as performing a set of core functions: assessing the health of the population, developing policies to address problems, and assuring that needed services are actually delivered. Assessment means monitoring health and investigating problems. Policy development means building plans, laws, and partnerships. Assurance means making sure prevention and care reach everyone, and evaluating whether programs work. Running through all of this is the idea of prevention, which comes in three levels. Primary prevention stops disease or injury before it ever occurs, by removing causes or raising resistance. Secondary prevention detects disease early, before symptoms or complications, so it can be treated while it is still easy to manage. Tertiary prevention acts after disease is established, reducing its harm, preventing complications, and restoring function. The levels form a timeline from before disease, to early disease, to established disease. A complete health strategy uses all three, but public health puts the most weight on primary prevention, because stopping a problem is usually cheaper and kinder than fixing it later."},{"heading":"Key methods & examples","text":"Primary prevention examples include vaccination, clean water and sanitation, seatbelt laws, tobacco taxes, and healthy school meals - all acting before any disease appears. Secondary prevention examples include screening programs that find disease early: blood pressure checks, mammography for breast cancer, cervical screening, and newborn blood-spot tests. The goal there is early detection in people who feel well, so treatment starts sooner and works better. Tertiary prevention examples include cardiac rehabilitation after a heart attack, physical therapy after a stroke, and good diabetes management to prevent blindness and amputation. To classify any action, ask when it acts relative to the disease. A flu shot given to a healthy person is primary. A screening test that catches an early cancer is secondary. A rehabilitation program for someone already diagnosed is tertiary. The same disease can involve all three: for cervical cancer, vaccination is primary, regular screening is secondary, and treatment plus follow-up care is tertiary. Being able to sort interventions this way helps planners see gaps and decide where added effort would save the most lives for the lowest cost."},{"heading":"Your turn","text":"Classify each as primary, secondary, or tertiary prevention, then check below. 1) A nationwide childhood vaccination program. 2) A mammogram offered to women with no symptoms. 3) Cardiac rehabilitation after a heart attack. 4) Adding fluoride to drinking water to prevent tooth decay. 5) A blood pressure screening clinic at a pharmacy. 6) Which of the three core functions covers monitoring the population''s health and investigating problems? Answers: 1) Primary - it prevents disease before it starts. 2) Secondary - it detects disease early in people who feel well. 3) Tertiary - it limits harm and restores function after disease. 4) Primary - it removes a cause before decay occurs. 5) Secondary - early detection of a hidden problem. 6) Assessment, the function that monitors health and investigates problems. Notice that four of the five actions are either primary or secondary, which reflects public health''s strong preference for acting early."},{"heading":"Common mistakes & exit ticket","text":"A frequent error is to confuse secondary and tertiary prevention. Secondary prevention targets people who feel well, finding hidden disease early; tertiary prevention targets people who are already diagnosed, limiting the harm. Another mistake is to assume primary prevention is always medical - many of its biggest wins are laws, taxes, and engineering, not drugs. A third mistake is to treat the three levels as rivals; a strong strategy for a given disease usually runs all three at once. Exit ticket: (a) Name the three levels of prevention in time order. (b) At which level does a screening test for symptom-free people belong? (c) Which core function makes sure that needed services actually reach people? Answers: (a) primary, secondary, tertiary; (b) secondary prevention; (c) assurance, the function that delivers and evaluates services. Carry this frame forward - it organizes nearly everything that follows in the course."}]}'::jsonb, 'Primary stops disease before it starts, secondary catches it early, tertiary limits damage once it is established - remember the order primary, secondary, tertiary as early to late.', 13),
  (4, 'Determinants of health and health equity', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"By the end of this lesson you will be able to explain what determines health, name the major categories of determinants, and define health equity and how it differs from simple equality. You will be able to argue, with examples, why medical care is only one of several forces that shape how long and how well people live. Warm-up: think of two newborns in the same country, one in a wealthy neighborhood and one in a poor one. Before either has seen a doctor, which is likely to live longer, and why? Hold your reasoning, because this lesson explains the pattern behind your intuition. The idea that health is shaped far upstream of the hospital is one of the most important and sometimes surprising lessons in the field, and it reshapes where public health chooses to spend its effort."},{"heading":"The idea","text":"Health is determined by far more than genes and medical care. Researchers group the determinants of health into several broad categories: individual behavior such as diet, exercise, smoking, and alcohol use; the social and economic environment, including income, education, employment, and social support; the physical environment, such as clean air, safe water, and housing; and access to health services. Genetics matter too, but for whole populations the social and economic conditions often matter most. These everyday conditions - the circumstances in which people are born, grow, live, work, and age - are called the social determinants of health. Because these conditions are unevenly distributed, health is unevenly distributed too. This leads to the idea of health equity: the principle that everyone should have a fair and just opportunity to be as healthy as possible. Equity is not the same as equality. Equality means giving everyone the same thing; equity means giving people what they need to reach a fair outcome, which may mean directing more resources to those who start with less. A health disparity that is avoidable and unfair is called a health inequity."},{"heading":"Key methods & examples","text":"Consider life expectancy. Within a single city, neighborhoods only a few kilometers apart can differ in average life expectancy by ten years or more, tracking closely with income, education, and housing quality rather than with the number of hospitals nearby. That gap is a signal that upstream conditions are doing the heavy lifting. Education is a powerful example of a social determinant: more schooling is linked to better health across many countries, partly through higher income, safer work, and better information. Housing is another: damp, crowded, or unsafe homes raise rates of asthma, injury, and infection. To improve equity, public health looks upstream. Rather than only treating asthma attacks, it may fund home repairs to remove mold; rather than only counseling on diet, it may work to bring affordable fresh food into neighborhoods that lack it. These upstream actions aim at the root conditions, so the benefit reaches many people and tends to last. Measuring equity means breaking health data down by income, geography, and other groupings to see who is being left behind, then directing effort there."},{"heading":"Your turn","text":"Answer, then check below. 1) Name the four broad categories of determinants of health described above. 2) What are the social determinants of health, in one sentence? 3) Explain the difference between equality and equity. 4) What makes a health difference count as an inequity rather than just a disparity? 5) Give one upstream action a public health team could take to reduce childhood asthma. Answers: 1) Individual behavior; social and economic environment; physical environment; and access to health services (genetics are also a factor). 2) The everyday conditions in which people are born, grow, live, work, and age, which shape their health. 3) Equality gives everyone the same thing; equity gives people what they need to reach a fair outcome, which may mean more for those with less. 4) It is an inequity when the difference is avoidable and unfair, not merely a natural variation. 5) Funding home repairs to remove damp and mold, among other options."},{"heading":"Common mistakes & exit ticket","text":"A common mistake is to assume that health is mostly about health care. For populations, the social and economic conditions usually matter more than the number of clinics. Another mistake is to blame individuals alone for unhealthy behavior while ignoring the conditions that make the healthy choice hard - the cheap, available, heavily marketed option often wins. A third mistake is to treat equity and equality as the same thing; aiming for a fair outcome sometimes requires unequal inputs. Exit ticket: (a) True or false: for whole populations, social and economic conditions often matter more for health than medical care. (b) Define health equity. (c) Why might an equitable program give more resources to some groups than others? Answers: (a) true; (b) the principle that everyone should have a fair and just opportunity to be as healthy as possible; (c) because people who start with greater disadvantage need more support to reach a fair health outcome."}]}'::jsonb, 'A determinant is a cause of health or illness; the social determinants are the everyday conditions - income, education, housing, work - that shape health long before anyone reaches a clinic.', 13),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"The central strategy that distinguishes public health from clinical medicine is...","options":["surgery","prevention across populations","individual billing","hospital construction"],"answer":1,"explanation":"Public health specializes in preventing disease across whole populations, while clinical medicine treats individual patients."},{"prompt":"Giving a flu vaccine to a healthy person is an example of...","options":["primary prevention","secondary prevention","tertiary prevention","rehabilitation"],"answer":0,"explanation":"The vaccine acts before any disease appears, which defines primary prevention."},{"prompt":"A mammogram offered to a woman with no symptoms is...","options":["primary prevention","secondary prevention","tertiary prevention","a cure"],"answer":1,"explanation":"Secondary prevention detects disease early in people who feel well, so it can be treated sooner."},{"prompt":"The three core functions of public health are best summarized as...","options":["diagnose, treat, bill","assessment, policy development, assurance","research, surgery, nursing","testing, isolation, fines"],"answer":1,"explanation":"Public health assesses population health, develops policy, and assures that services are delivered and evaluated."},{"prompt":"The everyday conditions of income, education, housing, and work that shape health are called...","options":["genetic factors","social determinants of health","clinical outcomes","vital signs"],"answer":1,"explanation":"These social determinants often influence population health more than medical care does."},{"prompt":"Health equity means...","options":["giving everyone exactly the same resources","a fair and just opportunity for everyone to be as healthy as possible","only treating the sickest patients","ignoring differences between groups"],"answer":1,"explanation":"Equity aims at a fair outcome, which can require giving more support to those who start with less - unlike plain equality."}]}'::jsonb, null, 8),
  (6, 'Epidemiology basics and surveillance', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"By the end of this lesson you will be able to define epidemiology, distinguish incidence from prevalence, explain what risk means and how it is compared across groups, and describe what public health surveillance is for. You will be able to read a simple statement about a disease and say whether it describes new cases or existing cases. Warm-up: suppose a report says that in one year a town had 50 new cases of a disease, and that 300 people in the town currently live with it. Which number is a count of new cases, and which is a count of everyone affected right now? Keep your answer in mind. Epidemiology is sometimes called the basic science of public health, because it supplies the measurements that everything else depends on. Getting comfortable with a few of its core measures will make the rest of the course much clearer, and it will help you judge health claims you meet in daily life."},{"heading":"The idea","text":"Epidemiology is the study of how often diseases and other health events occur in populations, and why. It gives public health its numbers. Two core measures are incidence and prevalence. Incidence is the rate of new cases arising in a population over a period of time; it captures how fast a disease is spreading or appearing. Prevalence is the proportion of a population that has the condition at a given moment; it captures the total existing burden. A short, severe illness may have high incidence but low prevalence, because cases resolve quickly, while a long-lasting condition can have modest incidence yet high prevalence because cases accumulate. Risk is the probability that a person develops a condition over a period. Epidemiologists compare risk between groups to find causes, often using a relative risk, which is the risk in an exposed group divided by the risk in an unexposed group. A relative risk above one suggests the exposure raises risk. Surveillance is the ongoing, systematic collection and analysis of health data so that problems are spotted early and responses can be judged."},{"heading":"Key methods & examples","text":"Suppose a town of 10,000 people records 50 new cases of an infection during one year. The incidence is 50 per 10,000 per year. If, at the end of that year, 300 people are living with a chronic condition, the prevalence is 300 per 10,000, or 3 percent. Now compare risk. If smokers have a lung cancer risk of 20 per 1,000 and non-smokers have 2 per 1,000, the relative risk is 20 divided by 2, which is 10: smokers face about ten times the risk. Such comparisons, made carefully, are how epidemiology links causes to effects. Surveillance puts these measures to work continuously. Health departments track notifiable diseases, monitor emergency room visits, and watch laboratory reports so that a rise above the expected level triggers investigation. During an outbreak, a sudden jump in incidence is often the first alarm. A classic early example is John Snow mapping cholera cases around a single London water pump in 1854, using the pattern of cases to point to the source - an origin story for the whole field."},{"heading":"Your turn","text":"Work these out, then check below. 1) Define incidence and prevalence in your own words. 2) A city of 100,000 has 200 new cases of a disease this year. What is the incidence per 100,000? 3) If 5,000 people in that city currently live with a chronic condition, what is the prevalence as a percentage? 4) Exposed group risk is 40 per 1,000; unexposed risk is 10 per 1,000. What is the relative risk? 5) What is the purpose of public health surveillance? Answers: 1) Incidence is the rate of new cases over a period; prevalence is the share of people with the condition at a point in time. 2) 200 per 100,000 per year. 3) 5,000 out of 100,000 is 5 percent. 4) 40 divided by 10 equals 4, so four times the risk. 5) To collect and analyze health data continuously so problems are detected early and responses can be evaluated."},{"heading":"Common mistakes & exit ticket","text":"The most common mistake is to mix up incidence and prevalence. Remember: incidence is new cases over a period, prevalence is all existing cases at a moment. A second mistake is to read a relative risk as a chance of harm by itself; a relative risk of 10 is only meaningful next to the underlying risk, which may still be small. A third mistake is to confuse correlation with causation - two things rising together does not prove one causes the other, so epidemiologists weigh evidence carefully before claiming a cause. Exit ticket: (a) Which measure counts new cases over time? (b) If exposed risk is 30 per 1,000 and unexposed is 15 per 1,000, what is the relative risk? (c) What does surveillance do for an outbreak response? Answers: (a) incidence; (b) 30 divided by 15 equals 2; (c) it detects the rise early and lets responders track whether their actions are working."}]}'::jsonb, 'Incidence counts NEW cases over a period; prevalence counts ALL existing cases at a moment - new versus existing is the key distinction.', 14),
  (7, 'Communicable disease control, outbreaks, and vaccination', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"After this lesson you will be able to describe how communicable diseases spread, name the main tools used to control them, explain what happens during an outbreak investigation, and define herd immunity. You will be able to explain why vaccination protects not only the person vaccinated but also the community around them. Warm-up: if a single person with a contagious illness walks into a crowded room, what features of that room and those people decide how many others get sick? List two or three factors in your head. Keep them in mind, because this lesson is about exactly those factors and how public health changes them. Communicable disease control is one of the oldest and most successful areas of the field, responsible for some of history''s greatest gains in human life expectancy, and its basic logic is surprisingly simple once you see it."},{"heading":"The idea","text":"Communicable diseases are caused by infectious agents such as bacteria, viruses, and parasites that pass from person to person, from animals to people, or through food, water, air, or insect carriers. Control works by breaking the chain of transmission, which has links: a source of infection, a route of spread, and a susceptible host. Public health can act on each link. It can reduce the source through treatment and isolation of cases, block the route through clean water, sanitation, hygiene, safe food, and masks, and protect the host through vaccination. Vaccination is especially powerful because it adds a community effect. When a high enough proportion of a population is immune, the pathogen can no longer find enough new hosts to keep spreading, and transmission collapses. This is herd immunity, and it indirectly protects people who cannot be vaccinated, such as newborns or those with weak immune systems. The share of the population that must be immune to reach this point depends on how contagious the disease is: the more contagious, the higher the threshold."},{"heading":"Key methods & examples","text":"When an outbreak is suspected, investigators follow a well-worn sequence: confirm that an outbreak is real, define a case, find cases and count them, describe the pattern by person, place, and time, form a hypothesis about the cause, test it, and put control measures in place. A classic step is drawing an epidemic curve, a graph of cases over time that can reveal whether people shared a single source or are infecting one another. Contact tracing then finds exposed people so they can be tested, treated, or isolated before they spread the illness further. Vaccination campaigns show the community effect in action. Measles is highly contagious, so roughly 95 percent of a population needs immunity to stop its spread; when coverage falls below that, outbreaks return. The eradication of smallpox, declared in 1980, was achieved not by vaccinating everyone but by finding each outbreak and vaccinating the ring of people around it until the virus had nowhere left to go. These examples show control as a mix of surveillance, rapid response, and prevention working together."},{"heading":"Your turn","text":"Answer, then check below. 1) Name the three links in the chain of infection. 2) Give one public health action that targets each link. 3) In your own words, what is herd immunity? 4) Why does a more contagious disease require a higher share of the population to be immune? 5) List two steps of an outbreak investigation. Answers: 1) A source of infection, a route of transmission, and a susceptible host. 2) Source: treat and isolate cases; route: clean water and hygiene; host: vaccination. 3) When enough of a population is immune, the pathogen cannot spread easily, which protects even those who are not immune. 4) Because each infected person tends to infect more others, so a larger immune fraction is needed to stop the chain. 5) Any two of: confirm the outbreak, define and find cases, describe person-place-time, form and test a hypothesis, and apply control measures."},{"heading":"Common mistakes & exit ticket","text":"A common mistake is to think vaccination only protects the individual who receives it; in fact high coverage protects the whole community through herd immunity. Another mistake is to assume an outbreak is over once cases stop appearing on one day, when late cases and new chains can follow - investigators keep watching. A third mistake is to treat all diseases as equally contagious; the immunity threshold for a highly contagious disease like measles is far higher than for many others. Exit ticket: (a) What is the term for indirect protection of non-immune people when most of a population is immune? (b) Which link in the chain of infection does clean water target? (c) Which human disease has been eradicated worldwide? Answers: (a) herd immunity; (b) the route of transmission; (c) smallpox, declared eradicated in 1980."}]}'::jsonb, 'Herd immunity means that when a large enough share of a population is immune, a pathogen cannot spread easily, which protects even those who are not immune.', 14),
  (8, 'Chronic disease, behavior, and the environment', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"By the end of this lesson you will be able to describe what chronic diseases are, name the main behavioral risk factors behind them, and explain how environmental and occupational hazards affect population health. You will be able to say why these problems call for prevention aimed at whole populations, not only advice to individuals. Warm-up: think about the leading causes of death in wealthy countries today - heart disease, cancer, stroke, diabetes. Are these mostly caught from other people, like infections, or do they build up slowly over years? Hold your answer. As infectious diseases came under control in many countries, this slower, noncommunicable group became the dominant health challenge, a shift sometimes called the epidemiologic transition. Understanding its causes, and how much of it is preventable, is central to modern public health, and it connects directly to the determinants and the levels of prevention you have already met."},{"heading":"The idea","text":"Chronic, noncommunicable diseases are long-lasting conditions that are generally not passed from person to person, including cardiovascular disease, cancer, chronic respiratory disease, and diabetes. Together they cause the majority of deaths worldwide. They share a small set of modifiable behavioral risk factors: tobacco use, unhealthy diet, physical inactivity, and the harmful use of alcohol. These behaviors raise intermediate risks such as high blood pressure, high blood sugar, raised cholesterol, and obesity, which in turn drive the diseases. Because the risk factors are modifiable, much of this burden is preventable. Alongside behavior sits the environment. Environmental health studies how air, water, soil, chemicals, noise, and climate affect health; air pollution alone contributes to millions of early deaths each year. Occupational health focuses on hazards at work, from dust and chemicals to repetitive strain and injury. Both fields show that risk is often built into the surroundings, which is why population-level action - cleaner air standards, safer workplaces, healthier food environments - can prevent disease more broadly than individual advice alone."},{"heading":"Key methods & examples","text":"Tobacco control is the model success story. Rather than only urging smokers to quit, public health raises tobacco taxes, bans smoking in indoor public places, requires plain packaging and warnings, and restricts advertising. These population measures have driven down smoking rates and, with them, lung cancer and heart disease. Diet and activity are tackled similarly: reformulating food to cut salt and sugar, clear front-of-pack labels, and urban design that makes walking and cycling easy. For the environment, setting and enforcing air quality standards reduces heart and lung disease across an entire city at once, and providing clean cooking fuels cuts household air pollution. In occupational health, requiring guards on machines, limiting exposure to hazardous dust, and mandating protective equipment prevent injury and disease on a large scale. The common thread is that changing the environment and the default choices is usually more effective than relying on willpower, because it reaches everyone and makes the healthy option the easy one. This is primary prevention applied to slow, lifestyle-linked, and environmental disease."},{"heading":"Your turn","text":"Answer, then check below. 1) Name three examples of chronic, noncommunicable diseases. 2) List the four main modifiable behavioral risk factors behind them. 3) Why are these factors called modifiable? 4) Give one population-level measure that reduces smoking. 5) What is the difference between environmental health and occupational health? Answers: 1) Any three of cardiovascular disease, cancer, chronic respiratory disease, and diabetes. 2) Tobacco use, unhealthy diet, physical inactivity, and harmful use of alcohol. 3) Because they can be changed, unlike fixed factors such as age or inherited risk. 4) Any of: higher tobacco taxes, indoor smoking bans, plain packaging and warnings, or advertising restrictions. 5) Environmental health looks at hazards in the general surroundings such as air and water; occupational health looks at hazards specifically in the workplace."},{"heading":"Common mistakes & exit ticket","text":"A common mistake is to see chronic disease as purely a matter of personal choice. Choices matter, but they are heavily shaped by price, marketing, and the environment, so population measures often work better than advice alone. Another mistake is to forget that chronic disease is now the leading cause of death in most of the world, including many lower-income countries, not only rich ones. A third mistake is to overlook the environment and the workplace as sources of disease that individuals cannot fix on their own. Exit ticket: (a) Name the four leading behavioral risk factors for chronic disease. (b) Give one reason population-level action can beat individual advice. (c) Which field addresses hazards specifically at work? Answers: (a) tobacco use, unhealthy diet, physical inactivity, and harmful alcohol use; (b) it reaches everyone and makes the healthy choice the easy default, rather than relying on willpower; (c) occupational health."}]}'::jsonb, 'Behavioral risk factors such as tobacco, poor diet, inactivity, and harmful alcohol use are called modifiable, meaning they can be changed - unlike age or inherited risk.', 13),
  (9, 'Health promotion, policy, global health, and systems', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"By the end of this lesson you will be able to explain what health promotion and health policy are, describe what global health adds to the picture, recall a few landmark milestones in public health history, and outline how health systems and major organizations fit together. You will be able to see how the pieces from earlier lessons combine into action at the level of a whole society and the whole world. Warm-up: think of one health rule or program where you live - a smoking ban, a vaccination schedule, a food label, a safe-water standard. Who decided it, who pays for it, and who makes sure it happens? Hold those questions. This final content lesson zooms out from single interventions to the structures and decisions that put them in place, because good science only improves health when systems and policies carry it into daily life, fairly and at scale."},{"heading":"The idea","text":"Health promotion is the process of enabling people to increase control over and improve their health, working not only on behavior but on the conditions that shape it. Health policy is the set of decisions, laws, and funding choices that a society makes to protect and improve health, from tobacco taxes to clean air standards to insurance rules. Policy is one of public health''s most powerful levers because it changes the default conditions for everyone at once. Global health extends these concerns across borders, focusing on health problems and solutions that affect people worldwide and especially on reducing inequities between countries. Delivering all of this requires health systems: the people, institutions, and resources that provide services and run prevention programs, ideally organized so that everyone can get needed care without financial hardship, an aim known as universal health coverage. Many organizations share this work: national and local health departments, the World Health Organization that coordinates globally, and many nonprofit and community groups. Together they turn evidence into programs, and programs into healthier populations."},{"heading":"Key methods & examples","text":"Public health history offers landmark milestones worth knowing. In the nineteenth century, sanitation and clean water systems in growing cities cut deadly outbreaks of cholera and typhoid and added years to life expectancy, arguably the single greatest public health achievement. Vaccination grew from a local practice into a global tool, culminating in the eradication of smallpox, declared in 1980 after a worldwide campaign. Twentieth-century advances in food safety, safer workplaces, motor-vehicle safety, and tobacco control each saved large numbers of lives. On the policy side, framework agreements on tobacco and standards for air and water quality show how written rules translate into prevention at scale. In global health, coordinated programs have driven polio to the edge of eradication and expanded childhood vaccination across low-income countries. Health systems make these gains durable: a system with strong primary care, reliable surveillance, and broad coverage can both respond to emergencies and steadily prevent disease. The lesson is that science, policy, and organized systems must work together, each supplying what the others cannot."},{"heading":"Your turn","text":"Answer, then check below. 1) In one sentence, what is health promotion? 2) Why is policy such a powerful tool in public health? 3) What does global health add beyond national public health? 4) Name two landmark milestones in public health history. 5) What does universal health coverage aim to achieve? Answers: 1) It is the process of enabling people to increase control over and improve their health, acting on both behavior and conditions. 2) Because it changes the default conditions for a whole population at once, through laws, taxes, and funding. 3) It addresses health problems and inequities that cross borders and affect people worldwide. 4) Any two of: sanitation and clean water in the nineteenth century, the eradication of smallpox in 1980, advances in food and vehicle safety, and tobacco control. 5) That everyone can obtain needed health services without suffering financial hardship."},{"heading":"Common mistakes & exit ticket","text":"A common mistake is to think health improves mainly through new medical discoveries; in practice, sanitation, safety laws, and vaccination programs have added more years of life than most treatments. Another mistake is to treat global health as charity rather than as a shared interest, since diseases and their solutions cross borders. A third mistake is to imagine that good evidence improves health on its own; without functioning systems and supportive policy, knowledge sits unused. Exit ticket: (a) Which nineteenth-century advance is often called the greatest public health achievement? (b) What is the aim of universal health coverage? (c) Name the international body that coordinates global public health. Answers: (a) sanitation and clean water supplies; (b) that everyone can get needed care without financial hardship; (c) the World Health Organization. With this, you have seen how prevention, measurement, disease control, and policy combine into the full practice of public health."}]}'::jsonb, 'Health promotion enables people to take control of their health; health policy sets the rules and funding that make healthy choices possible across a whole society.', 14),
  (10, 'Key terms', 'vocab', '{"items":[{"term":"public health","translation":"the organized effort of society to protect and improve the health of whole populations, with an emphasis on prevention","example":"Chlorinating a city''s water supply is public health in action, preventing illness for everyone at once."},{"term":"primary prevention","translation":"action that stops disease or injury before it ever occurs, by removing causes or raising resistance","example":"A vaccine given to a healthy person is primary prevention."},{"term":"incidence","translation":"the rate of new cases of a disease arising in a population over a period of time","example":"Fifty new infections in a town of 10,000 in one year is an incidence of 50 per 10,000 per year."},{"term":"prevalence","translation":"the proportion of a population that has a condition at a given point in time","example":"If 300 of 10,000 people currently live with a condition, the prevalence is 3 percent."},{"term":"epidemiology","translation":"the study of how often diseases and health events occur in populations, and why","example":"Epidemiology linked smoking to lung cancer by comparing risk between smokers and non-smokers."},{"term":"herd immunity","translation":"the indirect protection that arises when enough of a population is immune that a pathogen can no longer spread easily","example":"High measles vaccination coverage creates herd immunity that shields newborns too young to be vaccinated."},{"term":"social determinants of health","translation":"the everyday conditions - income, education, housing, work - in which people live that shape their health","example":"Two neighborhoods a few kilometers apart can differ in life expectancy because of social determinants of health."},{"term":"health equity","translation":"the principle that everyone should have a fair and just opportunity to be as healthy as possible","example":"Directing extra resources to an underserved area to close a life-expectancy gap pursues health equity."}]}'::jsonb, null, 9)
) as v(pos, title, kind, body, notes, mins)
where not exists (
